import * as React from "react";
import { cx } from "./cx";

export interface NavigationMenuProps extends React.HTMLAttributes<HTMLElement> {
  items: Array<{ label: React.ReactNode; href: string; current?: boolean }>;
}

/** Links in a row; the current page is ink. */
export function NavigationMenu({ items, className, ...props }: NavigationMenuProps) {
  return (
    <nav className={cx("rs-nav", className)} {...props}>
      {items.map((item, index) => (
        <a key={index} href={item.href} aria-current={item.current ? "page" : undefined}>
          {item.label}
        </a>
      ))}
    </nav>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Navigation menu: quiet links; the current page is ink ── */
.rs-nav{display:flex;align-items:center;gap:22px}
.rs-nav a{font-size:14px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);text-decoration:none;transition:color .2s ease}
.rs-nav a:hover,.rs-nav a[aria-current="page"]{color:var(--text)}
